$ErrorActionPreference='Stop'
$projectRoot=(Resolve-Path (Join-Path $PSScriptRoot '..\..\..\..')).Path
function Read-Json([string]$Path){if(-not(Test-Path -LiteralPath $Path -PathType Leaf)){throw "input-not-found: $Path"};$raw=[Text.UTF8Encoding]::new($false,$true).GetString([IO.File]::ReadAllBytes((Resolve-Path $Path).Path));$raw|ConvertFrom-Json}
function Hash([object]$Value){$sha=[Security.Cryptography.SHA256]::Create();try{$j=$Value|ConvertTo-Json -Depth 50 -Compress;([BitConverter]::ToString($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes($j)))).Replace('-','').ToLowerInvariant()}finally{$sha.Dispose()}}
$route=Read-Json $KnowledgeRouteReceiptPath
$reuse=$null;$reuseHash=$null
if(-not [string]::IsNullOrWhiteSpace($ReuseFromReceiptPath)){$reuse=Read-Json $ReuseFromReceiptPath;$reuseHash=(Get-FileHash (Join-Path $projectRoot $ReuseFromReceiptPath) -Algorithm SHA256).Hash.ToLowerInvariant();if([string]$reuse.recordType -cne 'DesignSystemProfileReceipt' -or [string]$reuse.status -cne 'accepted'){throw 'blocked.round-05.reuse-source-not-accepted'}}
if([string]$route.recordType -cne 'KnowledgeRouteReceipt' -or [string]$route.status -notin @('accepted','partial')){throw 'blocked.round-05.missing-route'}
