$expectedRoutePlanHash=if($route.PSObject.Properties['routePlanHash']){[string]$route.routePlanHash}else{[string]$route.routeHash}; $gate = & (Join-Path $projectRoot '.agents/skills/es-web-generation-round-05-capability-design/scripts/Test-ESRound05ABCDHardGate.ps1') -ReceiptPath $ABCDReceiptPath -TaskId ([string]$route.taskId) -RoutePlanHash $expectedRoutePlanHash -SourceScopeHash ([string]$route.sourceScopeHash); if($LASTEXITCODE -and $LASTEXITCODE -ne 0){throw 'blocked.round-05.abcd-hard-gate'}
