foreach($name in $required){$p=$packet.PSObject.Properties[$name];if($null-eq$p -or $null-eq$p.Value -or @($p.Value).Count -eq 0){throw "blocked.round-05.design-incomplete: $name"}}
$candidates=@($packet.divergenceCandidates)
if($candidates.Count -lt 3){throw 'blocked.round-05.divergence-insufficient'}
$reasons=@($candidates|Where-Object{$_.PSObject.Properties['discardReason'] -and -not [string]::IsNullOrWhiteSpace([string]$_.discardReason)})
if($reasons.Count -eq 0){throw 'blocked.round-05.divergence-insufficient: discard reasons required'}
