if(@($packet.motionEffectLibrary).Count -eq 0 -or $null -eq $packet.effectUsagePolicy.defaultDensity){throw 'blocked.round-05.effect-policy-missing'}
if([string]$packet.effectUsagePolicy.defaultDensity -notin @('high','very-high')){throw 'blocked.round-05.effect-policy-missing: default density must be high'}
