if(@($packet.subagentPlan.children).Count -lt 3 -or @($packet.subagentReceipts).Count -lt @($packet.subagentPlan.children).Count){throw 'blocked.round-05.child-join-incomplete'}
if($null -eq $packet.abccNegotiation.aIntentEnvelopeHash -or @($packet.abccNegotiation.capabilityOffers).Count -eq 0 -or $null -eq $packet.abccNegotiation.normalizedEvidence){throw 'blocked.round-05.abcc-negotiation-missing'}
if([string]$packet.PSObject.Properties['templateSource'] -and -not [string]::IsNullOrWhiteSpace([string]$packet.templateSource)){throw 'blocked.round-05.template-rejection'}
$redesignTemplate=Join-Path $projectRoot 'ES/Automation/ABCD/github-atlas-redesign.html'
if(-not (Test-Path -LiteralPath $redesignTemplate -PathType Leaf)){throw 'blocked.round-05.deep-design-template-missing'}
